pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple mock oracle that implements IOracleProvider
        // We'll use a minimal contract for the oracle
        MockOracle mockOracle = new MockOracle();

        // Prepare product info with the mock oracle (must be a contract)
        C.ProductInfo memory info;
        info.name = "Test";
        info.symbol = "TST";
        info.oracle = mockOracle;
        // Other fields - defaults are fine since we only test oracle()
        info.maintenance = UFixed18Lib.ZERO;
        info.fundingFee = UFixed18Lib.ZERO;
        info.makerFee = UFixed18Lib.ZERO;
        info.takerFee = UFixed18Lib.ZERO;
        info.positionFee = UFixed18Lib.ZERO;
        info.makerLimit = UFixed18Lib.ZERO;
        // PayoffDefinition - just use a valid dummy
        info.payoffDefinition.payoffType = PayoffDefinitionLib.PayoffType.NONE;
        info.payoffDefinition.payoffDirection = PayoffDefinitionLib.PayoffDirection.NONE;

        // Initialize the product (msg.sender becomes the controller)
        c.initialize(info);

        // Now oracle() should return the mock oracle address
        // In reference: returns address(mockOracle)
        // In bug: returns address(0)
        bool oracleIsSet = address(c.oracle()) != address(0);
        assertTrue(oracleIsSet);
    }
}

