        // Alternative: use vm.etch to set code at an address to make it a contract.
        address oracleAddr = address(0x100);
        vm.etch(oracleAddr, hex"00"); // minimal contract code (just a STOP)

        // Build PayoffDefinition struct (payoffType=0, payoffDirection=0, data=bytes30(0))
        bytes memory payoffDefData = new bytes(30); // all zeros
        C.ProductInfo memory productInfo;
        productInfo.name = "Test";
        productInfo.symbol = "TST";
        productInfo.payoffDefinition = C.PayoffDefinition({payoffType: C.PayoffDefinitionLib.PayoffType(0), payoffDirection: C.PayoffDefinitionLib.PayoffDirection(0), data: bytes30(payoffDefData)});
        productInfo.oracle = IOracleProvider(oracleAddr);
        productInfo.maintenance = UFixed18.wrap(0);
        productInfo.fundingFee = UFixed18.wrap(fundingFeeValue);
        productInfo.makerFee = UFixed18.wrap(0);
        productInfo.takerFee = UFixed18.wrap(0);
        productInfo.positionFee = UFixed18.wrap(0);
        productInfo.makerLimit = UFixed18.wrap(0);
        productInfo.utilizationCurve = C.JumpRateUtilizationCurve({
            minRate: C.PackedFixed18.wrap(0),
            maxRate: C.PackedFixed18.wrap(0),
            targetRate: C.PackedFixed18.wrap(0),
            targetUtilization: C.PackedUFixed18.wrap(0)
        });

        // Initialize with msg.sender = this (acts as controller) - but the initialize modifier expects version 1 and a controller.
        // We need to set up the controller storage to pass isProduct checks? No, we just need to call initialize.
        // The initialize function in C calls __UControllerProvider__initialize(IController(msg.sender)), which stores the controller.
