        c.initialize(productInfo);

        // Now call fundingFee()
        UFixed18 result = c.fundingFee();
        // Reference should return 0.5e18, bug returns 0
        assertTrue(UFixed18.unwrap(result) == fundingFeeValue, "Funding fee should be 0.5e18");
    }
}

